import{_ as a,o as t,c as n,ae as o}from"./chunks/framework.sRTLHEzD.js";const i="/heidrun_code/screenshots/features/panes.png",m=JSON.parse('{"title":"The panes","description":"Each pane of Heidrun Code shows a real terminal, so Claude Code, Codex, and Antigravity look and work exactly as you know them.","frontmatter":{"description":"Each pane of Heidrun Code shows a real terminal, so Claude Code, Codex, and Antigravity look and work exactly as you know them."},"headers":[],"relativePath":"features/panes.md","filePath":"features/panes.md"}'),r={name:"features/panes.md"};function s(h,e,d,l,p,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="the-panes" tabindex="-1">The panes <a class="header-anchor" href="#the-panes" aria-label="Permalink to &quot;The panes&quot;">​</a></h1><p>A coding agent is a program that runs in a terminal. Many tools put the coding agent inside their own window, and then the coding agent no longer looks or works as you know it.</p><h2 id="real-terminals" tabindex="-1">Real terminals <a class="header-anchor" href="#real-terminals" aria-label="Permalink to &quot;Real terminals&quot;">​</a></h2><p>Each pane of Heidrun Code shows the real terminal of Herdr, the terminal multiplexer that Heidrun Code needs. Claude Code, Codex, and Antigravity look and work exactly as in Herdr: the same colors, the same keys, and the same menus. Heidrun Code wraps nothing and rewrites nothing.</p><p>A workspace is one project folder. A workspace has tabs, and a tab has one or more panes.</p><p><img src="'+i+'" alt="The Heidrun Code window with three panes in one tab: Claude Code on the left, Codex at the top right, and a second Claude Code under Codex. The Needs you sidebar section is on the right."></p><h2 id="split-a-pane" tabindex="-1">Split a pane <a class="header-anchor" href="#split-a-pane" aria-label="Permalink to &quot;Split a pane&quot;">​</a></h2><p>The header of each pane has two split buttons: &quot;Split right&quot; and &quot;Split down&quot;.</p><ul><li>A click on a split button starts the default command of a new tab in the new pane, for example a new Claude Code.</li><li>A shift click on a split button starts a plain terminal in the new pane.</li></ul><h2 id="pin-a-pane" tabindex="-1">Pin a pane <a class="header-anchor" href="#pin-a-pane" aria-label="Permalink to &quot;Pin a pane&quot;">​</a></h2><p>Click the pin button in the header of a pane. The pane goes into the column of pinned panes, at the right edge of the viewport. A pinned pane stays visible when you select another tab or another workspace, so you can watch one coding agent while you work somewhere else. Click the pin button again to unpin the pane.</p><h2 id="drop-an-image" tabindex="-1">Drop an image <a class="header-anchor" href="#drop-an-image" aria-label="Permalink to &quot;Drop an image&quot;">​</a></h2><p>Drop an image file on a terminal. Heidrun Code pastes the image into the terminal, so the coding agent of the pane receives it, as when you paste an image yourself.</p><h2 id="go-back-and-go-forward" tabindex="-1">Go back and go forward <a class="header-anchor" href="#go-back-and-go-forward" aria-label="Permalink to &quot;Go back and go forward&quot;">​</a></h2><p>Heidrun Code remembers the panes that had the focus, in every workspace and every tab. This list is the pane focus history.</p><ul><li>The Back button and the Forward button, at the top of the window, move through the pane focus history, as in a web browser.</li><li>The keys ⌘[ and ⌘] do the same as the two buttons.</li><li>Press and hold a button to see the list of the panes, then click the pane that you want.</li></ul><p>A pane goes into the pane focus history only when the pane keeps the focus for half a second. A pane that you only pass through does not fill the list.</p><p><em>Odin has two ravens that tell him what happens in the nine worlds. You have the Back button and the Forward button.</em></p>',18)])])}const w=a(r,[["render",s]]);export{m as __pageData,w as default};
